from pathlib import Path
import re
r=Path('README.md'); s=r.read_text(encoding='utf-8')
s=s.replace('- las páginas **173–177** ya poseen representación lexicográfica estructurada, pero su reconciliación exhaustiva página por página sigue pendiente;', '- la página **173** tiene sus **42 candidatos canónicos reconciliados**: 40 `article` y 2 `continuation`, sin candidatos estructuralmente `unresolved`; se documentan 4 falsos negativos seleccionados (`000599` Rueda, `000600` Saber generalmente, `000605` Sahumar, `000607` Salitral), L-010/L-011/R-015 quedan `merged_articles`, R-018 `undersegmented`, permanecen 29 fronteras `pending_promotion` y el censo visible sigue no exhaustivo; p.174 tiene 48 candidatos y `000614` (`Si, adv. para afirmar`) es un comienzo superior sin frontera propia antes de L-001 (`Si, conj.`);\n- las páginas **174–177** ya poseen representación lexicográfica estructurada, pero su reconciliación exhaustiva página por página sigue pendiente;',1)
s=re.sub(r'en \*\*p\.172\*\* quedan 41 `pending_promotion`\. Las páginas 145–172.*?El siguiente frente geométrico es la \*\*página 173\*\*.*?\.', 'en **p.172** quedan 41 `pending_promotion`; y en **p.173** quedan 29 `pending_promotion`. Las páginas 145–173 tienen reconciliación de candidatos completa, pero sus censos visibles aún no se consideran exhaustivos. El siguiente frente geométrico es la **página 174**, con 48 candidatos canónicos —26 izquierda y 22 derecha—; la capa seleccionada comienza con `000614` (`Si, adv. para afirmar. Hebui.`), comienzo superior sin frontera propia antes de L-001 (`Si, conj. Soc.`).', s, count=1, flags=re.S)
